// Recomputes every derived number used in the pet-physics batch.
// Inputs are values read from the cited sources; outputs are printed and exported.
const c = 299792458;                 // m/s, exact (CODATA)
const mec2 = 510.99895069;           // keV, CODATA 2022
const out = {};
const r = (x, n) => Number(x.toFixed(n));

// --- F-18 half-life
const tHalfDDEP_h = 1.82890;         // LNHB/DDEP 2014 evaluation
out.halfLife_DDEP_min = r(tHalfDDEP_h * 60, 3);
out.halfLife_DDEP_s = r(tHalfDDEP_h * 3600, 1);
out.halfLife_ENSDF_min = 109.77;     // ENSDF (Tilley 1995) via IAEA LiveChart
out.halfLife_TUNL_min = 109.732;     // TUNL 2019 recommended
out.halfLife_spread_min = r(out.halfLife_ENSDF_min - out.halfLife_TUNL_min, 3);
const T = out.halfLife_DDEP_min;
const lambda_s = Math.LN2 / (T * 60);
out.decayConstant_per_s = lambda_s;
for (const m of [60, 110, 120, 220, 360, 720, 1440]) out['fractionLeft_' + m + 'min'] = r(Math.pow(2, -m / T), 4);
out.fractionLeft_10halfLives = Math.pow(2, -10);
out.tenHalfLives_h = r(10 * T / 60, 1);

// --- branching and 511 keV photons
const bplus = 96.86;                 // % DDEP
out.ec_percent = r(100 - bplus, 2);
out.photons511_per100decays = r(2 * bplus, 2);   // DDEP lists 193.72
// --- positron end-point energy from Q value
out.Emax_keV = r(1655.9 - 2 * mec2, 1);          // DDEP lists 633.9
out.meanOverMax = r(249.5 / 633.9, 3);

// --- annihilation
out.mec2_keV = mec2;
out.pairEnergy_MeV = r(2 * mec2 / 1000, 4);
// non-collinearity: blur FWHM = D * theta / 4 (theta in rad)
const deg = Math.PI / 180;
out.blurCoeff_from_0p5deg = r(0.5 * deg / 4, 5);          // ~0.0022
out.angle_from_0p00243_deg = r(4 * 0.00243 / deg, 3);     // Shibuya coefficient -> degrees
for (const D of [764, 786, 800, 820, 842, 900]) {
  out['blur_mm_D' + D + '_0.0022'] = r(0.0022 * D, 2);
  out['blur_mm_D' + D + '_0.00243'] = r(0.00243 * D, 2);
}
// --- light travel
out.lightTravel_cm_per_ns = r(c * 1e-9 * 100, 2);
for (const d of [0.576, 0.70, 0.78, 0.82]) out['transit_ns_' + d + 'm'] = r(d / c * 1e9, 2);

// --- time of flight: dx = c * dt / 2
out.tof = {};
for (const ps of [100, 178, 189, 210, 214, 228, 256, 310, 332, 375, 400, 505, 527.5, 585, 600]) out.tof[ps] = r(c * ps * 1e-12 / 2 * 100, 2); // cm

// --- scintillation light per 511 keV photon
const ly = { LSO_luxium: 26000, LYSO_luxium: 33200, LSO_LYSO_low: 25000, LSO_LYSO_high: 34000, BGO_low: 8000, BGO_high: 10000, BGO_mid: 9000 };
out.lightPer511 = {};
for (const k in ly) out.lightPer511[k] = Math.round(ly[k] * mec2 / 1000);
out.lightRatio_LYSO_to_BGO = r(33200 / 9000, 1);
out.decayRatio_BGO_to_LSO = r(300 / 40, 1);

// --- Compton scatter: E' = 511 / (2 - cos(theta))
out.scatterEnergy_keV = {};
for (const a of [10, 20, 30, 45, 60, 90, 180]) out.scatterEnergy_keV[a] = r(mec2 / (2 - Math.cos(a * deg)), 1);
out.maxAngleAccepted_deg = {};
for (const thr of [425, 430, 435, 440, 450]) out.maxAngleAccepted_deg[thr] = r(Math.acos(2 - mec2 / thr) / deg, 1);

// --- injected activity
const mCi = 37; // MBq per mCi, exact
out.activity = {
  '5mCi_MBq': 5 * mCi, '10mCi_MBq': 10 * mCi, '20mCi_MBq': 20 * mCi,
  decaysPerSec_185MBq: 185e6, decaysPerSec_370MBq: 370e6,
  positronsPerSec_185MBq: r(185e6 * bplus / 100, 0), positronsPerSec_370MBq: r(370e6 * bplus / 100, 0),
  perKg_70kg_3MBq: 3 * 70, perKg_70kg_3p5MBq: 3.5 * 70, perKg_70kg_5MBq: 5 * 70,
  perKg_185_over_70: r(185 / 70, 2), perKg_370_over_70: r(370 / 70, 2),
  EANM_75kg_2min_le30: 14 * 75 / 2, EANM_75kg_2min_gt30: 7 * 75 / 2, EANM_75kg_3min_le30: 14 * 75 / 3,
  EANM_perKg_2min_gt30: 7 / 2, EANM_perKg_2min_le30: 14 / 2,
};
// number of atoms and mass of F-18 in 370 MBq
const N370 = 370e6 / lambda_s;
out.activity.atoms_370MBq = N370;
out.activity.mass_ng_370MBq = r(N370 * 18.000937 / 6.02214076e23 * 1e9, 4);
out.activity.atoms_185MBq = 185e6 / lambda_s;
out.activity.left_after_60min_of_370 = r(370 * Math.pow(2, -60 / T), 0);
out.activity.effDose_mSv_185 = r(0.019 * 185, 2); out.activity.effDose_mSv_370 = r(0.019 * 370, 2);

// --- crystal counts
out.crystals = {
  Vision600: 8 * 38 * 8 * 25,        // rings x blocks/ring x mini-blocks x crystals
  VisionQuadra: 32 * 38 * 8 * 25,
  DiscoveryMI_4ring: 4 * 136 * 36,   // rings x blocks x (4x9)
  Vereos: 18 * 40 * 32,
  mCT: 4 * 48 * 13 * 13,
  uEXPLORER: 13440 * 42,
  uEXPLORER_blocks: 8 * 24 * 70,
  OmniLegend32: 22 * 24 * 72,
};
out.uEXPLORER_axial_cm = r(8 * 24.02 + 7 * 0.26, 2);

// --- sensitivity as a percentage of decays (1 cps/kBq = 1 count per 1000 decays = 0.1 %)
const sens = { GeminiTF: 6.6, Vereos: 5.2, mCTFlow: 9.6, DiscoveryMI4: 13.7, Vision600: 16.4, uMIPanorama35: 20.1, OmniLegend32: 47.3, PennPET64: 55, Quadra_MRD85: 83.4, Quadra_MRD322: 176.0, uEXPLORER: 174, PanoramaGS: 176.3 };
out.sensPercent = {}; for (const k in sens) out.sensPercent[k] = r(sens[k] / 10, 2);
out.sensRatio_uEXPLORER_vs = {}; for (const k of ['Vereos', 'mCTFlow', 'DiscoveryMI4', 'Vision600']) out.sensRatio_uEXPLORER_vs[k] = r(174 / sens[k], 1);
out.afovRatio_194_over_20 = r(194 / 20, 1);
out.snrGain_sqrt40 = r(Math.sqrt(40), 1);
out.activity_370_over_40 = r(370 / 40, 2);

module.exports = out;
if (require.main === module) console.log(JSON.stringify(out, null, 1));
EOF
node calc.js

